const MEDIA={cover:'',directory:'',contact:''};
const projects=[
 {title:'云端木棉岛',type:'IP DESIGN / 品牌与角色',range:[4,20],cover:4,desc:'围绕南航「云端伙伴」展开的四角色 IP 设计。从角色形象、主题场景到运营页面与文创延展，建立统一的蓝白视觉世界。'},
 {title:'AIGC 视觉实验',type:'AIGC VISUAL / 运营与动态',range:[21,37],cover:21,desc:'结合 AIGC 探索游戏运营视觉、活动 H5 与广告短片。从主题概念、画面构图到页面延展，让创意与信息层级共同服务内容表达。'},
 {title:'流浪星球',type:'BRAND DESIGN / 公益品牌',range:[38,54],cover:39,desc:'以流浪动物救助与领养传播为主题，通过品牌识别、角色、社交传播和线下活动物料，构建年轻化的公益品牌体验。'},
 {title:'执笔宣战',type:'KV DESIGN / 主题视觉',range:[55,66],cover:56,desc:'以主题主视觉为起点，展开字体、系列海报、场景与活动物料设计，用统一的色彩和图形语言连接不同触点。'},
 {title:'博物馆在掌心',type:'UI DESIGN / 数字体验',range:[67,77],cover:67,desc:'博物馆数字界面设计探索，以内容浏览、信息组织和参观体验为核心，呈现完整的界面系统。'}
];
const $=s=>document.querySelector(s);const imgPath=n=>`assets/project-originals/work-${String(n).padStart(2,'0')}.jpg`;
$('#cards').innerHTML=projects.map((p,i)=>`<button class="work-card" style="--r:${[-3,3,-2,2,-3][i]}deg;--i:${i}" data-project="${i}" aria-label="查看${p.title}"><div class="card-number"><span>NO. 0${i+1}</span><span>HAN LAB ✳</span></div><img loading="lazy" src="${imgPath(p.cover)}" alt="${p.title}项目封面"><h3>${p.title}</h3><p>${p.type}</p><div class="card-bottom"><span>2024—2026</span><span>展开作品 ↗</span></div></button>`).join('');
function printCards(){const c=$('#cards');c.classList.remove('printing');void c.offsetWidth;c.classList.add('printing');$('#print').textContent='正在打印…';setTimeout(()=>$('#print').textContent='重新打印 ↓',1700)}$('#print').onclick=printCards;
const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){printCards();observer.unobserve(e.target)}})},{threshold:.15});observer.observe($('#cards'));
let active=0;let scrollBefore=0;function showProject(i){active=i;const p=projects[i];if($('#project').hidden)scrollBefore=window.scrollY;$('#project-counter').textContent=`0${i+1} / 05 — ${p.type.split(' / ')[0]}`;$('#project-content').innerHTML=`<div class="project-intro"><small>SELECTED WORK / 0${i+1}</small><h1>${p.title}</h1><p>${p.desc}</p><p>向下滚动，浏览完整项目 ↓</p></div>`+Array.from({length:p.range[1]-p.range[0]+1},(_,j)=>`<img class="project-image" src="${imgPath(p.range[0]+j)}" alt="${p.title}作品展示，第${j+1}页" loading="${j?'lazy':'eager'}" decoding="async">`).join('');$('#project').hidden=false;document.body.classList.add('modal-open');$('#project').scrollTop=0;history.replaceState(null,'',`#project-${i+1}`);$('#back').focus();$('#next').textContent=`下一份：${projects[(i+1)%projects.length].title} →`}
function closeProject(){ $('#project').hidden=true;document.body.classList.remove('modal-open');history.replaceState(null,'','#works');window.scrollTo({top:scrollBefore,behavior:'instant'});$(`[data-project="${active}"]`).focus({preventScroll:true})}
document.querySelectorAll('[data-project]').forEach(b=>b.onclick=()=>showProject(Number(b.dataset.project)));$('#back').onclick=closeProject;$('#back-bottom').onclick=closeProject;$('#next').onclick=()=>showProject((active+1)%projects.length);$('#project-contact').onclick=()=>{closeProject();$('#contact').scrollIntoView({behavior:'smooth'})};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#project').hidden)closeProject()});
let timer;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),2500)}document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.dataset.copy);toast('已复制，期待你的消息！')}catch{toast('请长按或选中联系方式复制')}});
Object.entries(MEDIA).forEach(([key,src])=>{if(!src)return;const host=document.querySelector(`[data-video="${key}"]`);host.style.position='relative';const v=document.createElement('video');v.src=src;v.muted=true;v.playsInline=true;v.className='video-layer';v.preload='metadata';host.prepend(v);new IntersectionObserver((entries,o)=>{if(entries[0].isIntersecting){v.play().catch(()=>{});o.disconnect()}},{threshold:.3}).observe(host)});
const match=location.hash.match(/^#project-(\d)$/);if(match&&projects[+match[1]-1]){scrollBefore=$('#works').offsetTop;showProject(+match[1]-1)}
